# Standard library
import uuid

# Third-party
from sqlalchemy import ForeignKey, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, ReferenceWithFactorMixin


class CoreRefDifficultySport(Base, ReferenceWithFactorMixin):
    __tablename__ = "core_ref_difficulty_sport"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        comment=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid(). Uniquely identifies a sport-specific "
            "difficulty grade (e.g. - for hiking, for ski touring, for "
            "climbing)."
        ),
    )
    sport_type_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("core_ref_sport_type.id"),
        nullable=True,
        comment=(
            "Optional FK to core_ref_sport_type.id linking this "
            "sport-specific difficulty grade to its parent sport type. NULL "
            "when the grade applies across multiple sports."
        ),
    )
